extern "C" {__declspec(dllexport) extern const UINT D3D12SDKVersion=721;__declspec(dllexport) const char*D3D12SDKPath=".\\D3D12\\";}
static void ck(HRESULT hr){if(FAILED(hr))throw std::runtime_error("HRESULT="+std::to_string(unsigned(hr)));}
static ID3D12Resource* buffer(ID3D12Device*d,UINT64 n,D3D12_HEAP_TYPE type){D3D12_HEAP_PROPERTIES hp{};hp.Type=type;D3D12_RESOURCE_DESC r{};r.Dimension=D3D12_RESOURCE_DIMENSION_BUFFER;r.Width=n;r.Height=1;r.DepthOrArraySize=r.MipLevels=1;r.SampleDesc.Count=1;r.Layout=D3D12_TEXTURE_LAYOUT_ROW_MAJOR;ID3D12Resource*b=nullptr;ck(d->CreateCommittedResource(&hp,D3D12_HEAP_FLAG_NONE,&r,type==D3D12_HEAP_TYPE_UPLOAD?D3D12_RESOURCE_STATE_GENERIC_READ:D3D12_RESOURCE_STATE_COPY_DEST,nullptr,IID_PPV_ARGS(&b)));return b;}
static void barrier(ID3D12GraphicsCommandList*c,ID3D12Resource*r,D3D12_RESOURCE_STATES a,D3D12_RESOURCE_STATES b){if(a==b)return;D3D12_RESOURCE_BARRIER x{};x.Type=D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;x.Transition={r,D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES,a,b};c->ResourceBarrier(1,&x);}
static void env(const char*k,const char*v){if(_putenv_s(k,v))throw std::runtime_error("environment update");std::wstring wk(k,k+strlen(k)),wv(v,v+strlen(v));if(_wputenv_s(wk.c_str(),wv.c_str()))throw std::runtime_error("wide environment update");}
static void flags(const wchar_t*path){std::ifstream f(path);if(!f)throw std::runtime_error("flags missing");std::string s;while(std::getline(f,s)){auto p=s.find_first_not_of(" \t\r");if(p==std::string::npos||s[p]=='#'||s[p]==';')continue;s=s.substr(p);auto eq=s.find('=');if(eq==std::string::npos)continue;auto name=s.substr(0,eq),value=s.substr(eq+1);while(!name.empty()&&isspace((unsigned char)name.back()))name.pop_back();while(!value.empty()&&isspace((unsigned char)value.back()))value.pop_back();auto start=value.find_first_not_of(" \t");value=start==std::string::npos?"":value.substr(start);if(name.rfind("DLSS5_",0))continue;env(name.c_str(),value.c_str());}}
int wmain(int argc,wchar_t**argv){try{
 if(argc<5||argc>7){fprintf(stderr,"usage: benchmark_frame ASSETS FLAGS 720|900|1080 OUTPUT_PREFIX [frames=30] [temporal=1]\n");return 2;}
 const UINT H=wcstoul(argv[3],nullptr,10),W=H==720?1280:H==900?1600:1920,N=argc>5?wcstoul(argv[5],nullptr,10):30;const bool temporal=argc<7||wcstoul(argv[6],nullptr,10)!=0;if((H!=720&&H!=900&&H!=1080)||!N||N>10000)throw std::runtime_error("invalid height/frame count");flags(argv[2]);
 env("DLSS5_NETWORK_720P",H==720?"1":"0");env("DLSS5_NETWORK_HEIGHT",std::to_string(H).c_str());env("DLSS5_DEBUG_DUMPS","");env("DLSS5_BLACK_PROBE","0");env("DLSS5_GAME_PROBE","0");env("DLSS5_SHOW_FPS","0");env("DLSS5_OVERLAP","0");env("DLSS5_TEST_SUBMISSION_TIMING","0");
 const IID experimental={0x76f5573e,0xf13a,0x40f5,{0xb2,0x97,0x81,0xce,0x9e,0x18,0x93,0x3f}};ck(D3D12EnableExperimentalFeatures(1,&experimental,nullptr,nullptr));
 IDXGIFactory6*f=nullptr;ck(CreateDXGIFactory2(0,IID_PPV_ARGS(&f)));ID3D12Device*d=nullptr;for(UINT i=0;;i++){IDXGIAdapter1*a=nullptr;if(f->EnumAdapterByGpuPreference(i,DXGI_GPU_PREFERENCE_HIGH_PERFORMANCE,IID_PPV_ARGS(&a))==DXGI_ERROR_NOT_FOUND)break;DXGI_ADAPTER_DESC1 info{};a->GetDesc1(&info);if(info.VendorId==0x1002){ck(D3D12CreateDevice(a,D3D_FEATURE_LEVEL_12_0,IID_PPV_ARGS(&d)));wprintf(L"adapter=%ls\n",info.Description);}a->Release();if(d)break;}f->Release();if(!d)throw std::runtime_error("AMD adapter missing");
 ID3D12CommandQueue*q=nullptr;D3D12_COMMAND_QUEUE_DESC qd{};ck(d->CreateCommandQueue(&qd,IID_PPV_ARGS(&q)));NativeGameSubmission submit;submit.Create(q);
 D3D12_HEAP_PROPERTIES hp{};hp.Type=D3D12_HEAP_TYPE_DEFAULT;D3D12_RESOURCE_DESC td{};td.Dimension=D3D12_RESOURCE_DIMENSION_TEXTURE2D;td.Width=W;td.Height=H;td.DepthOrArraySize=td.MipLevels=1;td.Format=DXGI_FORMAT_R8G8B8A8_UNORM;td.SampleDesc.Count=1;ID3D12Resource*target=nullptr,*motion=nullptr;ck(d->CreateCommittedResource(&hp,D3D12_HEAP_FLAG_NONE,&td,D3D12_RESOURCE_STATE_COPY_DEST,nullptr,IID_PPV_ARGS(&target)));D3D12_PLACED_SUBRESOURCE_FOOTPRINT fp{};UINT64 bytes;d->GetCopyableFootprints(&td,0,1,0,&fp,nullptr,nullptr,&bytes);auto*upload=buffer(d,bytes,D3D12_HEAP_TYPE_UPLOAD);auto*rb=buffer(d,bytes,D3D12_HEAP_TYPE_READBACK);void*p=nullptr;D3D12_RANGE none{};ck(upload->Map(0,&none,&p));memset(p,0,size_t(bytes));for(UINT y=0;y<H;y++)for(UINT x=0;x<W;x++){auto*v=(unsigned char*)p+fp.Offset+size_t(y)*fp.Footprint.RowPitch+x*4;v[0]=32+x*192/W;v[1]=32+y*192/H;v[2]=((x/24+y/24)%2)?192:64;v[3]=255;}upload->Unmap(0,nullptr);
 auto copy=[&](ID3D12GraphicsCommandList*c,ID3D12Resource*dst,ID3D12Resource*src){D3D12_TEXTURE_COPY_LOCATION a{},b{};a.pResource=dst;a.Type=D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;b.pResource=src;b.Type=D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;b.PlacedFootprint=fp;c->CopyTextureRegion(&a,0,0,0,&b,nullptr);};
 ID3D12Resource*zero=nullptr;{td.Format=DXGI_FORMAT_R16G16_FLOAT;ck(d->CreateCommittedResource(&hp,D3D12_HEAP_FLAG_NONE,&td,D3D12_RESOURCE_STATE_COPY_DEST,nullptr,IID_PPV_ARGS(&motion)));zero=buffer(d,bytes,D3D12_HEAP_TYPE_UPLOAD);ck(zero->Map(0,&none,&p));memset(p,0,size_t(bytes));zero->Unmap(0,nullptr);auto colorfp=fp;fp.Footprint.Format=DXGI_FORMAT_R16G16_FLOAT;submit.Submit([&](ID3D12GraphicsCommandList*c){copy(c,motion,zero);barrier(c,motion,D3D12_RESOURCE_STATE_COPY_DEST,D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);});submit.Flush();fp=colorfp;}
 std::wstring assets=argv[1],prefix=argv[4];auto noise=NativeReadF32(assets+L"\\noise.f32","noise");NativeGameFrame frame;NativeGameFrame::TemporalConfig tc{W,H,W,H};frame.Create(q,target,noise,assets,nullptr,&tc);noise.clear();noise.shrink_to_fit();
 ID3D12QueryHeap*queries=nullptr;D3D12_QUERY_HEAP_DESC hd{};hd.Type=D3D12_QUERY_HEAP_TYPE_TIMESTAMP;hd.Count=2;ck(d->CreateQueryHeap(&hd,IID_PPV_ARGS(&queries)));auto*times=buffer(d,16,D3D12_HEAP_TYPE_READBACK);UINT64 frequency;ck(q->GetTimestampFrequency(&frequency));if(!frequency)throw std::runtime_error("zero frequency");std::vector<double>gpu,cpu;FILE*csv=_wfopen((prefix+L".csv").c_str(),L"wb");if(!csv)throw std::runtime_error("output directory missing");fprintf(csv,"frame,warmup,gpu_queue_ms,cpu_wall_ms\n");
 for(UINT i=0;i<N+3;i++){// Restore frozen input outside timing; never recursively process overwritten output.
 submit.Submit([&](ID3D12GraphicsCommandList*c){copy(c,target,upload);});submit.Flush();auto begin=std::chrono::steady_clock::now();submit.Submit([&](ID3D12GraphicsCommandList*c){c->EndQuery(queries,D3D12_QUERY_TYPE_TIMESTAMP,0);});frame.ProcessSubmittedFrame(target,D3D12_RESOURCE_STATE_COPY_DEST,D3D12_RESOURCE_STATE_COPY_DEST,0,false,motion,!temporal||i==0);submit.Submit([&](ID3D12GraphicsCommandList*c){c->EndQuery(queries,D3D12_QUERY_TYPE_TIMESTAMP,1);c->ResolveQueryData(queries,D3D12_QUERY_TYPE_TIMESTAMP,0,2,times,0);});submit.Flush();double wall=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();D3D12_RANGE range{0,16};ck(times->Map(0,&range,&p));auto*t=(UINT64*)p;if(t[1]<=t[0])throw std::runtime_error("timestamp ordering");double ms=double(t[1]-t[0])*1000/frequency;times->Unmap(0,&none);fprintf(csv,"%u,%u,%.6f,%.6f\n",i,i<3,ms,wall);fflush(csv);if(i>=3){gpu.push_back(ms);cpu.push_back(wall);}printf("frame=%u warmup=%u gpu_queue_ms=%.3f cpu_wall_ms=%.3f\n",i,i<3,ms,wall);fflush(stdout);}
 fclose(csv);submit.Submit([&](ID3D12GraphicsCommandList*c){barrier(c,target,D3D12_RESOURCE_STATE_COPY_DEST,D3D12_RESOURCE_STATE_COPY_SOURCE);D3D12_TEXTURE_COPY_LOCATION a{},b{};a.pResource=rb;a.Type=D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;a.PlacedFootprint=fp;b.pResource=target;b.Type=D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;c->CopyTextureRegion(&a,0,0,0,&b,nullptr);barrier(c,target,D3D12_RESOURCE_STATE_COPY_SOURCE,D3D12_RESOURCE_STATE_COPY_DEST);});submit.Flush();D3D12_RANGE rr{0,SIZE_T(bytes)};ck(rb->Map(0,&rr,&p));FILE*out=_wfopen((prefix+L".ppm").c_str(),L"wb");if(!out)throw std::runtime_error("image output failed");fprintf(out,"P6\n%u %u\n255\n",W,H);unsigned lo=255,hi=0;double sum=0;for(UINT y=0;y<H;y++)for(UINT x=0;x<W;x++){auto*v=(unsigned char*)p+fp.Offset+size_t(y)*fp.Footprint.RowPitch+x*4;fwrite(v,1,3,out);for(int k=0;k<3;k++){lo=std::min(lo,unsigned(v[k]));hi=std::max(hi,unsigned(v[k]));sum+=v[k];}}fclose(out);rb->Unmap(0,&none);
 std::sort(gpu.begin(),gpu.end());double avg=std::accumulate(gpu.begin(),gpu.end(),0.)/N,median=(gpu[(N-1)/2]+gpu[N/2])/2,wall=std::accumulate(cpu.begin(),cpu.end(),0.)/N;printf("RESULT %ux%u temporal=%u frames=%u gpu_ms mean=%.3f median=%.3f min=%.3f fps_mean=%.2f fps_best=%.2f cpu_wall_mean_ms=%.3f rgb_min=%u max=%u mean=%.3f\n",W,H,temporal,N,avg,median,gpu[0],1000/avg,1000/gpu[0],wall,lo,hi,sum/(W*double(H)*3));printf("GPU queue elapsed includes submission gaps; excludes input restore, model initialization, game, capture, FSR4 and frame generation. RGBA8 color sanity does not prove finite internal residuals.\n");if(lo==hi)throw std::runtime_error("flat output sanity failure");
 if(temporal){submit.Submit([&](ID3D12GraphicsCommandList*c){copy(c,target,upload);});submit.Flush();frame.RequestTemporalDump(prefix);frame.ProcessSubmittedFrame(target,D3D12_RESOURCE_STATE_COPY_DEST,D3D12_RESOURCE_STATE_COPY_DEST,0,false,motion,false);submit.Flush();auto history=NativeReadF32(prefix+L"-history.f32","history sanity");size_t bad=0;for(float v:history)bad+=!std::isfinite(v);printf("history_float_values=%zu nonfinite=%zu (outside measured interval)\n",history.size(),bad);if(bad)throw std::runtime_error("nonfinite temporal history");}
 // All GPU work fenced before releasing caller resources; frame owns references.
 submit.Flush();times->Release();queries->Release();rb->Release();upload->Release();if(zero)zero->Release();if(motion)motion->Release();target->Release();q->Release();d->Release();return 0;
 }catch(const std::exception&e){fprintf(stderr,"benchmark failed: %s\n",e.what());return 1;}}
